import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int p = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        final long MOD = 1000000007L;
        long answer = 1;

        if (k == 0) {
            for (int i = 0; i < p - 1; ++i) {
                answer = (answer * p) % MOD;
            }
        } else {
            int[] parent = new int[p];
            int[] size = new int[p];
            for (int i = 0; i < p; ++i) {
                parent[i] = i;
                size[i] = 1;
            }
            int cc = p;

            // findRoot function
            java.util.function.Function<Integer, Integer> findRoot = new java.util.function.Function<Integer, Integer>() {
                public Integer apply(Integer x) {
                    while (parent[x] != x) {
                        parent[x] = parent[parent[x]];
                        x = parent[x];
                    }
                    return x;
                }
            };

            // unite function
            java.util.function.BiFunction<Integer, Integer, Boolean> unite = new java.util.function.BiFunction<Integer, Integer, Boolean>() {
                public Boolean apply(Integer a, Integer b) {
                    a = findRoot.apply(a);
                    b = findRoot.apply(b);
                    if (a.equals(b)) return false;
                    if (size[a] < size[b]) {
                        int temp = a;
                        a = b;
                        b = temp;
                    }
                    parent[b] = a;
                    size[a] += size[b];
                    cc--;
                    return true;
                }
            };

            for (int i = 0; i < p; ++i) {
                int to = (int)((long)k * i % p);
                unite.apply(i, to);
            }

            if (k > 1) {
                Set<Integer> components = new HashSet<>();
                for (int i = 0; i < p; ++i) {
                    components.add(findRoot.apply(i));
                }
                cc = components.size();
            }

            for (int i = 0; i < cc; ++i) {
                answer = (answer * p) % MOD;
            }
        }
        System.out.println(answer);
    }
}
